# Sample Input Data: N samples of N numbers
# Sample Input (e.g., for N=3: '1 2 3\n4 5 6\n7 8 9')

def maxNodeValue(root, keys):
    result = -sys.maxsize
    val_max = -sys.maxsize

    def helper(node, keys):
        if keys[node] > result:
            result =keys[node]
        if keys[node] > val_max:
            val_max = keys[node]

        if node.left:
            helper(node.left, keys)
        if node.right:
            helper(node.right, keys)

    if root is not None:
        helper(root, [int(k.strip()) for k in sys.stdin.readlines()]):
    print(val_max)
